// Compile-Time Polymorphism via NTTP and constexpr

template <int PolicyID>
struct PolicyEngine {
    static constexpr int calculate(int x) {
        if constexpr (PolicyID == 1) {
            return x * x;
        } else { // PolicyID 2
            return x + 100;
        }
    }
};

// Compile-time function selection (No Vtable indirection)
constexpr int V1 = PolicyEngine<1>::calculate(10); // Result 100
constexpr int V2 = PolicyEngine<2>::calculate(10); // Result 110

// The engine is resolved and instantiated at compile time.
// Faster than runtime virtual dispatch.
// Memory layout is optimized (no VTable overhead).
